const NEW_PAIR_EVENT = "0x0d3648bd0f6ba80134a33ba9275ac585d9d315f0ad8355cddefde31afa28d0e9"

type PairCreatedEvent struct {
	Token0    common.Address
	Token1    common.Address
	Pair      common.Address
	PairIndex *big.Int `abi:"arg3"`
}

func main() {
	err := godotenv.Load()
	if err != nil {
		log.Fatal("Error loading .env file")
	}

	log.Println("==> Starting PancakSwap V2 Buy Bot")

	log.Println("==> Initialize RPC listener")
	rpcUrl := os.Getenv("RPC_URL")

	client, err := ethclient.Dial(rpcUrl)
	if err != nil {
		log.Fatal(err)
	}

	pancakeSwapFactoryAddress := common.HexToAddress(PANCAKESWAP_FACTORY)

	filterQuery := ethereum.FilterQuery{
		Addresses: []common.Address{pancakeSwapFactoryAddress},
		Topics:    [][]common.Hash{{common.HexToHash(NEW_PAIR_EVENT)}},
	}

	newPairLogChannel := make(chan types.Log)

	log.Println("==> Listening to new pair events...")

	sub, err := client.SubscribeFilterLogs(context.Background(), filterQuery, newPairLogChannel)
	if err != nil {
		log.Fatal(err)
	}

	factoryAbi, err := abi.JSON(strings.NewReader(UNISWAP_V2_FACTORY_ABI))
	if err != nil {
		log.Fatal(err)
	}

	for {
		select {
		case err := <-sub.Err():
			log.Fatal(err)
		case vLog := <-newPairLogChannel:
			log.Println("")
			log.Println("==> New pair detected...")

			var event PairCreatedEvent

			if err := factoryAbi.UnpackIntoInterface(&event, "PairCreated", vLog.Data); err != nil {
				log.Println("==> failed to unpack event:", err)
				continue
			}

			if len(vLog.Topics) >= 3 {
				event.Token0 = common.HexToAddress(vLog.Topics[1].Hex())
				event.Token1 = common.HexToAddress(vLog.Topics[2].Hex())
			}

			log.Println("==> block: ", vLog.BlockNumber)
			log.Println("==> transaction: ", vLog.TxHash.Hex())
			log.Println("==> token0: ", event.Token0)
			log.Println("==> token1: ", event.Token1)
			log.Println("==> pair: ", event.Pair)
			log.Println("==> pair index: ", event.PairIndex)

			log.Println("")

		}
	}
}
